(ns tik.pq-fixture
  "ML-DSA signatures made by OpenSSL 3.5.8, so the verifier is checked
  against an implementation that is not the JDK's:

    openssl genpkey -algorithm ML-DSA-65 -out k.pem
    openssl pkey -in k.pem -pubout -outform DER -out pub.der
    printf 'tik-event-v1\\0' | cat - event.edn > msg.bin
    openssl pkeyutl -sign -rawin -inkey k.pem -in msg.bin -out sig.bin

  `sig-no-domain` signs `event.edn` without the prefix, and the
  ML-DSA-44 pair signs `msg.bin` with the wrong parameter set."
  (:import (java.util Base64)))

(defn- b64 ^bytes [^String s] (.decode (Base64/getDecoder) s))

(def event-text "{:event/actor \"alice\" :event/at #inst \"2026-11-23T20:00:00Z\"}")
(def event-bytes (.getBytes ^String event-text "UTF-8"))
(def public-key-b64 "")
(def public-key (b64 public-key-b64))
(def fingerprint "f5caf37f647871a1c4b28990a4b3c6bf0f19ab0ac28b2c319fa4196488403a10")
(def signature (b64 ""))
(def sig-no-domain (b64 ""))
(def public-key-44-b64 "")
(def public-key-44 (b64 public-key-44-b64))
(def signature-44 (b64 ""))
